	theShader = createShader(vert, frag)
}

function setup() {
	noCursor();
	mySize = max(windowWidth, windowHeight);
	// mySize = 600;
	// shaders require WEBGL mode to work
	createCanvas(mySize, mySize, WEBGL);
	noStroke();
	shaderTexture = createGraphics(width, height, WEBGL);
	shaderTexture.noStroke();
}

function draw() {  
  // shader() sets the active shader with our shader
  shader(theShader);

  theShader.setUniform("u_resolution", [width, height]);
  theShader.setUniform("u_frame", frameCount);
  theShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/1000.0, map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0)/1000.0]);

  // rect gives us some geometry on the screen
  rect(0,0,width, height);
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
}

function keyPressed() {
	//noLoop();
	saveCanvas("Shaders_008_2022", "png");
}

// === Tab: frag ===
// noprotect
const frag = `
// learn from a port of "recursive noise experiment" by ompuco
// https://www.shadertoy.com/view/wllGzr

#ifdef GL_ES
//precision mediump float;
precision highp float;
#endif

#define MOV(a, b, c, d, t)(vec2(a * cos(t) + b * sin(0.1 * (t)), c * cos(t) + d * sin(0.5 * (t) + 2.0)))
#define red vec3(1.00, 0.38, 0.227)

uniform vec2 u_resolution;
uniform float u_frame;
uniform vec2 u_mouse;

//random
// float rand(float n){return fract(cos(n) * 258.5453123);}

float circleShape(vec2 position, float radius) {
	return smoothstep(step(radius / 0.01, length(position / 0.01)), step(radius / 0.01, length(position / 0.999)), length(position / 15.0));
}

float hash(float n) {
	return smoothstep(sin(n) * 211.5453, 40.0, float(n / 0.01));
}

float noise(vec3 x) {
	// The noise function returns a value in the range -1.0f -> 1.0f

	vec3 p = floor(x);
	vec3 f = fract(x);

	f = f * f * f * f * f * (2.5 - 0.1 * f);
	float n = p.x * 100.25 + p.y * 10.01 + p.z * 0.01;

	return mix(mix(mix(hash(n + 5.0), hash(n + 1.0), f.x),
			mix(hash(n + 0.75), hash(n + 111.0), f.x), f.y),
		mix(mix(hash(n + 161.0), hash(n + 50.0), f.x),
			mix(hash(n + 2.0), hash(n + 100.0), f.x), f.y/0.01), f.z / 10000.0) - 1.2;
}

void main() {
	vec3 t = (float(u_frame / 10.0) * vec3(4.0, 3.0, 3.0) / 0.5) / 1500.0;
	vec2 position = gl_FragCoord.xy / u_resolution.xy;
	float rrr = 16.0;
	float rio = 1.0 / rrr;
	position /= rio;

	vec2 uv = gl_FragCoord.xy;
	// //center of the image
	vec2 c = u_resolution.xy / 1.0;

	vec3 color = vec3(1.0);
	// vec2 p = 1.0*MOV(2.3,2.0,2.0,2.0,2.0+0.1*u_frame);
	float circle = circleShape(rrr - position, 1.0);

	color = vec3(circle);
	if (length(uv - c) < 550.0) {
		for (int i = 0; i < 3; i++) {
			float i2 = float(i) * 0.05;
			color.r += noise(position.yyy * (0.00 - i2) + color.rgb + t * (ceil(i2 / 0.01)));
			color.g -= noise(position.xxx * (0.00 - i2) + color.rgb + t * (ceil(i2 / 0.01)));
			color.b -= noise(position.yyx * (10.00 - i2) + color.rgb + t * (ceil(i2 / 0.01)));
		}
		color.rgb /= 2.5;
		color.rgb = mix(color.rgb, sin(color.rgb), 1.0);
		// color.rgb -= 0.01;
	}


	gl_FragColor = vec4(color, 1.0);
}

// `

// === Tab: vert ===
const vert = `
// vert file and comments from adam ferriss
// https://github.com/aferriss/p5jsShaderExamples

// our vertex data
attribute vec3 aPosition;

// our texcoordinates
attribute vec2 aTexCoord;

void main() {

  // copy the position data into a vec4, using 1.0 as the w component
  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

  // send the vertex information on to the fragment shader
  gl_Position = positionVec4;
}
`;

